insert into public.lessons(id,module_id,title,status,version) values
('10101010-1010-4010-8010-101010101010',1,'Кто такой ученик?','published',1);
insert into public.lesson_blocks(lesson_id,position,kind,content) values
('10101010-1010-4010-8010-101010101010',1,'text',
 '{"heading":"Зачем этот путь","body":"Ученичество начинается с ответа на приглашение Иисуса. Его призыв касается не только того, что мы знаем, но и того, как мы живём рядом с Ним и с людьми. В этом занятии мы будем учиться следовать Иисусу, исполнять Его Слово, любить и помогать другому следовать за Ним. Видео не требуется: всё занятие доступно в тексте."}'),
('10101010-1010-4010-8010-101010101010',2,'scripture',
 '{"reference":"Мф. 4:19","translation":"Синодальный перевод","text":"и говорит им: идите за Мною, и Я сделаю вас ловцами человеков.","source":"https://free.bible/synodal/matthew/4/#v19"}'),
('10101010-1010-4010-8010-101010101010',3,'scripture',
 '{"reference":"Лк. 9:23","translation":"Синодальный перевод","text":"Ко всем же сказал: если кто хочет идти за Мною, отвергнись себя, и возьми крест свой, и следуй за Мною.","source":"https://free.bible/synodal/luke/9/#v23"}'),
('10101010-1010-4010-8010-101010101010',4,'scripture',
 '{"reference":"Ин. 8:31","translation":"Синодальный перевод","text":"Тогда сказал Иисус к уверовавшим в Него Иудеям: если пребудете в слове Моем, то вы истинно Мои ученики,","source":"https://free.bible/synodal/john/8/#v31"}'),
('10101010-1010-4010-8010-101010101010',5,'scripture',
 '{"reference":"Ин. 13:35","translation":"Синодальный перевод","text":"По тому узнают все, что вы Мои ученики, если будете иметь любовь между собою.","source":"https://free.bible/synodal/john/13/#v35"}'),
('10101010-1010-4010-8010-101010101010',6,'scripture',
 '{"reference":"Ин. 15:8","translation":"Синодальный перевод","text":"Тем прославится Отец Мой, если вы принесете много плода и будете Моими учениками.","source":"https://free.bible/synodal/john/15/#v8"}'),
('10101010-1010-4010-8010-101010101010',7,'scripture',
 '{"reference":"Мф. 28:19–20","translation":"Синодальный перевод","text":"Итак идите, научите все народы, крестя их во имя Отца и Сына и Святаго Духа, уча их соблюдать все, что Я повелел вам; и се, Я с вами во все дни до скончания века. Аминь","source":"https://free.bible/synodal/matthew/28/#v19"}'),
('10101010-1010-4010-8010-101010101010',8,'text',
 '{"heading":"Следовать — значит отвечать","body":"Иисус зовёт людей за Собой. В Евангелии ученика узнают не по количеству прослушанных уроков: он пребывает в Слове, любит людей и приносит плод. Следование не происходит в одиночестве: то, чему мы учимся у Иисуса, мы передаём другим, помогая им соблюдать Его слова. Отметьте, что именно услышали вы, прежде чем выбирать действие."}'),
('10101010-1010-4010-8010-101010101010',9,'question',
 '{"key":"q1","prompt":"Что в приглашении Иисуса «идите за Мною» касается вашей жизни сегодня?"}'),
('10101010-1010-4010-8010-101010101010',10,'question',
 '{"key":"q2","prompt":"Чем пребывание в слове Иисуса отличается для вас от одного лишь знания текста?"}'),
('10101010-1010-4010-8010-101010101010',11,'question',
 '{"key":"q3","prompt":"Как любовь между учениками может стать видимой в вашем окружении?"}'),
('10101010-1010-4010-8010-101010101010',12,'question',
 '{"key":"q4","prompt":"Кого вы можете поддержать в том, чтобы следовать за Иисусом и соблюдать Его слова?"}'),
('10101010-1010-4010-8010-101010101010',13,'practice',
 '{"heading":"От знания к конкретному шагу","body":"Назовите одно наблюдаемое действие на эту неделю. Вместо «буду больше любить» попробуйте «в среду выслушаю человека и помогу ему с конкретной нуждой». Выберите срок и человека, с которым поделитесь тем, что открыли в Слове."}'),
('10101010-1010-4010-8010-101010101010',14,'obedience_action',
 '{"heading":"Действие недели","body":"Сохраните решение, дату и человека. Возвратитесь после срока и честно отметьте, что произошло: сделал, пока нет или нужна помощь. Изучение урока не равно исполнению."}'),
('10101010-1010-4010-8010-101010101010',15,'person_selector',
 '{"heading":"Кому передам?","body":"Выберите человека из карты окружения или добавьте новое краткое имя. Факт передачи отметьте отдельно после разговора."}'),
('10101010-1010-4010-8010-101010101010',16,'prayer',
 '{"heading":"Молитва","body":"Иисус, научи меня идти за Тобой сегодня. Помоги мне услышать Твоё Слово, исполнить его и любить людей рядом со мной. Дай мне смелость и внимательность, чтобы помочь другому следовать за Тобой. Аминь."}'),
('10101010-1010-4010-8010-101010101010',17,'next_step',
 '{"heading":"Впереди — жизнь","body":"Вернитесь к своему действию после выбранного срока. Отметьте реальный результат, а не просмотр урока. Ваш следующий шаг — не баллы и не рейтинг, а верность в конкретном деле и передача услышанного."}');

insert into public.gbo_paths(id,title,published) values
('20202020-2020-4020-8020-202020202020','Слышать и исполнять',true);
insert into public.gbo_lessons(id,path_id,title,content) values
('30303030-3030-4030-8030-303030303030','20202020-2020-4020-8020-202020202020','Слышать и исполнять',
 '{
  "duration":"60–75 минут",
  "reference":"Мф. 7:24–27",
  "translation":"Синодальный перевод",
  "source":"https://free.bible/synodal/matthew/7/#v24",
  "scripture":"Итак всякого, кто слушает слова Мои сии и исполняет их, уподоблю мужу благоразумному, который построил дом свой на камне; и пошел дождь, и разлились реки, и подули ветры, и устремились на дом тот, и он не упал, потому что основан был на камне. А всякий, кто слушает сии слова Мои и не исполняет их, уподобится человеку безрассудному, который построил дом свой на песке; и пошел дождь, и разлились реки, и подули ветры, и налегли на дом тот и он упал, и было падение его великое.",
  "steps":[
    {"phase":"НАЗАД","title":"Благодарность и нужды","minutes":10,"prompt":"За что мы благодарны? Какая помощь нужна? Кому мы можем послужить?"},
    {"phase":"НАЗАД","title":"Прошлый шаг","minutes":8,"prompt":"Если это не первая встреча: что мы открыли в прошлый раз, что исполнили и кому передали? В первую встречу пропустите этот отчёт."},
    {"phase":"ВВЕРХ","title":"Слушаем Писание","minutes":10,"prompt":"Прочитайте Мф. 7:24–27 вслух дважды, затем перескажите текст своими словами. Не заменяйте текст мнениями."},
    {"phase":"ВВЕРХ","title":"Открываем вместе","minutes":17,"prompt":"Что узнаём о Боге, человеке и Иисусе? Чем отличаются два строителя? Что происходит с обоими домами? Где мы видим это в тексте?"},
    {"phase":"ВПЕРЁД","title":"Исполнить и передать","minutes":15,"prompt":"Какое конкретное действие и к какой дате сделает каждый? Кому передаст услышанное? Кому мы послужим как группа?"},
    {"phase":"ВПЕРЁД","title":"Следующая встреча и молитва","minutes":10,"prompt":"Назначьте следующую дату и следующего ведущего из участников. Помолитесь друг за друга и за исполнение Слова."}
  ]
 }'::jsonb);